CREATE TABLE IF NOT EXISTS queue_positions(turn TEXT PRIMARY KEY REFERENCES turns(id),position INTEGER NOT NULL) STRICT;
CREATE TRIGGER IF NOT EXISTS turn_stopped AFTER UPDATE OF status ON turns
WHEN NEW.status='cancelled' AND OLD.status<>'cancelled' AND NEW.stopped_at IS NULL
BEGIN UPDATE turns SET stopped_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id; END;
CREATE TABLE IF NOT EXISTS queue_edits(editor TEXT PRIMARY KEY,turn TEXT NOT NULL REFERENCES turns(id),state TEXT NOT NULL,original TEXT NOT NULL,expires_at INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE IF NOT EXISTS task_controls(id TEXT PRIMARY KEY,request TEXT NOT NULL,result TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY,turn TEXT NOT NULL REFERENCES turns(id),call_id TEXT NOT NULL,call TEXT NOT NULL,prompt TEXT NOT NULL,choices TEXT NOT NULL,answer TEXT,after_output INTEGER NOT NULL,after_action INTEGER NOT NULL,UNIQUE(turn,call_id)) STRICT;
CREATE TABLE IF NOT EXISTS question_answers(id TEXT PRIMARY KEY,request TEXT NOT NULL,result TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS turn_verification(turn TEXT PRIMARY KEY REFERENCES turns(id),nudged INTEGER NOT NULL DEFAULT 0,review TEXT,kind TEXT,stamp TEXT);
CREATE TABLE IF NOT EXISTS verification_artifacts(turn TEXT NOT NULL REFERENCES turns(id),source TEXT NOT NULL,file TEXT REFERENCES files(id),kind TEXT NOT NULL,stamp TEXT NOT NULL,PRIMARY KEY(turn,source)) STRICT;
CREATE TABLE IF NOT EXISTS queue_edit_commands(id TEXT PRIMARY KEY,request TEXT NOT NULL,result TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS queue_order_commands(id TEXT PRIMARY KEY,request TEXT NOT NULL,result TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS coordination(seq INTEGER PRIMARY KEY AUTOINCREMENT,turn TEXT NOT NULL REFERENCES turns(id),owner TEXT NOT NULL REFERENCES agents(id),target TEXT NOT NULL REFERENCES agents(id),kind TEXT NOT NULL,prompt TEXT NOT NULL,call TEXT NOT NULL,child TEXT REFERENCES turns(id)) STRICT;
CREATE TABLE IF NOT EXISTS compactions(scope TEXT PRIMARY KEY,version TEXT NOT NULL,through INTEGER NOT NULL,summary TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS compaction_sources(scope TEXT NOT NULL,seq INTEGER NOT NULL REFERENCES turns(seq),revision INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(scope,seq)) STRICT;
CREATE TABLE IF NOT EXISTS compaction_attempts(turn TEXT PRIMARY KEY REFERENCES turns(id),status TEXT NOT NULL,created TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS harness_steps(turn TEXT NOT NULL REFERENCES turns(id),id TEXT NOT NULL,name TEXT NOT NULL,state TEXT NOT NULL,PRIMARY KEY(turn,id)) STRICT;
CREATE TABLE IF NOT EXISTS harness_approvals(id TEXT PRIMARY KEY,turn TEXT NOT NULL REFERENCES turns(id),agent TEXT NOT NULL REFERENCES agents(id),runtime TEXT NOT NULL,workspace TEXT NOT NULL,kind TEXT NOT NULL,description TEXT NOT NULL,command TEXT,prefix TEXT,input TEXT NOT NULL,state TEXT NOT NULL,decision TEXT,revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE IF NOT EXISTS harness_policies(agent TEXT NOT NULL REFERENCES agents(id),runtime TEXT NOT NULL,workspace TEXT NOT NULL,prefix TEXT NOT NULL,PRIMARY KEY(agent,runtime,workspace,prefix)) STRICT;
CREATE TABLE IF NOT EXISTS harness_decisions(id TEXT PRIMARY KEY,request TEXT NOT NULL,result TEXT NOT NULL) STRICT;

CREATE TABLE IF NOT EXISTS image_generations(turn TEXT NOT NULL REFERENCES turns(id),call TEXT NOT NULL,file TEXT REFERENCES files(id),uncertain INTEGER NOT NULL,PRIMARY KEY(turn,call)) STRICT;
CREATE TABLE IF NOT EXISTS transcriptions(id TEXT PRIMARY KEY,file TEXT NOT NULL REFERENCES files(id),request TEXT NOT NULL,model TEXT NOT NULL,origin TEXT NOT NULL,status TEXT NOT NULL,result TEXT,created TEXT NOT NULL,usage TEXT) STRICT;

CREATE TABLE IF NOT EXISTS turn_step_diagnostics(
    turn TEXT NOT NULL REFERENCES turns(id), id TEXT NOT NULL, started TEXT, finished TEXT,
    arguments TEXT, result TEXT, failed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(turn,id)
) STRICT;
CREATE TABLE IF NOT EXISTS harness_stderr(
    call INTEGER PRIMARY KEY REFERENCES provider_calls(seq), tail TEXT NOT NULL
) STRICT;
